export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let wx = 0, wz = 0, dyDist = 0;
  let mEff = 0.78;
  let motorThrust = 0;
  let prevThrustCmd = 0.48;

  let rollTrim = 0, pitchTrim = 0, yawInt = 0;
  let refRoll = 0, refPitch = 0;

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let prevGate = null;
  let currentGate = null;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        motorThrust = 0;
      } else {
        // Update filtered motor thrust (lag ~ 0.04s)
        motorThrust += (16.0 * prevThrustCmd - motorThrust) * (1 - Math.exp(-dt / 0.04));

        const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
        const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);

        const bodyX = sp * cr, bodyZ = -sr;
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = cp * cr;
        const dirZ = -sy * bodyX + cy * bodyZ;

        const airborne = p.y > 0.082 && p.y < 2.88;
        const inRoom = Math.abs(p.x) < 2.80 && Math.abs(p.z) < 2.80;

        // Vertical observer
        const ayPred = airborne ? ((motorThrust * dirY - 0.42 * vy) / mEff - 9.81 + dyDist) : 0;
        const pyPred = py + vy * dt + 0.5 * ayPred * dt * dt;
        const vyPred = vy + ayPred * dt;
        const epY = p.y - pyPred;
        const evY = v.y - vyPred;
        py = pyPred + 0.75 * epY;
        vy = vyPred + 0.65 * evY + 10.0 * epY;
        if (airborne) {
          dyDist = clamp(dyDist + 28.0 * evY + 60.0 * epY, -6.5, 6.5);
          if (Math.abs(dyDist) > 0.2) {
            const dm = clamp(-0.025 * dyDist * dt, -0.005, 0.005);
            const oldM = mEff;
            mEff = clamp(mEff + dm, 0.58, 1.08);
            dyDist += (motorThrust * dirY) * (1 / oldM - 1 / mEff);
          }
        }

        // Actual thrust-to-mass ratio
        const tOverM = airborne
          ? clamp(motorThrust / mEff + dyDist / Math.max(0.5, dirY), 1.0, 28.0)
          : motorThrust / mEff;

        // Horizontal observers
        const ux = tOverM * dirX - (0.42 / mEff) * vx;
        const uz = tOverM * dirZ - (0.42 / mEff) * vz;
        const axPred = airborne ? (ux + wx) : 0;
        const azPred = airborne ? (uz + wz) : 0;

        const pxPred = px + vx * dt + 0.5 * axPred * dt * dt;
        const vxPred = vx + axPred * dt;
        const pzPred = pz + vz * dt + 0.5 * azPred * dt * dt;
        const vzPred = vz + azPred * dt;

        const epX = p.x - pxPred, evX = v.x - vxPred;
        const epZ = p.z - pzPred, evZ = v.z - vzPred;

        px = pxPred + 0.75 * epX;
        vx = vxPred + 0.65 * evX + 10.0 * epX;
        pz = pzPred + 0.75 * epZ;
        vz = vzPred + 0.65 * evZ + 10.0 * epZ;

        if (airborne && inRoom) {
          wx = clamp(wx + 38.0 * evX + 100.0 * epX, -11.0, 11.0);
          wz = clamp(wz + 38.0 * evZ + 100.0 * epZ, -11.0, 11.0);
        }

        // Attitude trim observer (compensates weak motor roll/pitch bias)
        if (airborne) {
          rollTrim = clamp(rollTrim + 1.8 * (refRoll - att.roll) * dt, -0.25, 0.25);
          pitchTrim = clamp(pitchTrim + 1.8 * (refPitch - att.pitch) * dt, -0.25, 0.25);
          yawInt = clamp(yawInt + att.yaw * dt, -0.6, 0.6);
        }
      }

      // Navigation state machine
      let tx = px, ty = 1.0, tz = pz;
      let vxFF = 0, vyFF = 0, vzFF = 0;
      let kpX = 6.0, kdX = 4.2;
      let kpZ = 7.5, kdZ = 4.8;
      let kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          if (currentGate) prevGate = currentGate;
          currentGate = { x: gate.x, y: gate.y, z: gate.z };
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }

        // Ensure we clear the previous gate before moving laterally in z/y
        if (prevGate && px < prevGate.x + 0.18) {
          tx = prevGate.x + 0.32;
          ty = prevGate.y;
          tz = prevGate.z;
          vxFF = 0.65;
          kpZ = 10.0; kdZ = 5.5;
        } else {
          const dzGate = Math.abs(pz - gate.z);
          const dyGate = Math.abs(py - gate.y);

          if (phase === 'align') {
            // Stay further back in x until z and y are close to gate center
            const xStandOff = (dzGate > 0.07 || dyGate > 0.12) ? 0.32 : 0.20;
            tx = gate.x - xStandOff;
            ty = gate.y;
            tz = gate.z;
            kpZ = 9.5; kdZ = 5.4;
            kpX = 6.5; kdX = 4.5;

            if (
              px > gate.x - 0.28 &&
              px < gate.x - 0.04 &&
              dzGate < 0.016 &&
              Math.abs(vz) < 0.09 &&
              dyGate < 0.055 &&
              Math.abs(vy) < 0.22 &&
              Math.abs(vx) < 0.28
            ) {
              settle++;
            } else {
              settle = Math.max(0, settle - 1);
            }
            if (settle >= 5) {
              phase = 'cross';
            }
          }

          if (phase === 'cross') {
            // Safety check before crossing the gate plane: if z or y drifts toward frame, abort!
            const dxToGate = gate.x - px;
            if (dxToGate > 0.01) {
              const tCross = clamp(dxToGate / Math.max(0.25, vx), 0.01, 0.22);
              const zPred = pz + vz * tCross;
              const yPred = py + vy * tCross;
              if (
                dzGate > 0.024 ||
                Math.abs(zPred - gate.z) > 0.026 ||
                dyGate > 0.095 ||
                Math.abs(yPred - gate.y) > 0.105
              ) {
                phase = 'align';
                settle = 0;
                tx = gate.x - 0.22;
                ty = gate.y;
                tz = gate.z;
                vxFF = -0.2;
                kpX = 8.5; kdX = 5.0;
                kpZ = 10.5; kdZ = 5.8;
              } else {
                tx = gate.x + 0.30;
                ty = gate.y;
                tz = gate.z;
                vxFF = 0.75;
                kpX = 7.0; kdX = 4.5;
                kpZ = 11.0; kdZ = 6.0;
              }
            } else {
              tx = gate.x + 0.30;
              ty = gate.y;
              tz = gate.z;
              vxFF = 0.75;
              kpZ = 11.0; kdZ = 6.0;
            }
          }
        }
      } else {
        // Landing after all 3 gates
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          if (currentGate) prevGate = currentGate;
          targetIndex = 3;
          phase = 'pad_approach';
          settle = 0;
        }

        if (prevGate && px < prevGate.x + 0.18) {
          tx = prevGate.x + 0.32;
          ty = prevGate.y;
          tz = prevGate.z;
          vxFF = 0.6;
          kpZ = 10.0; kdZ = 5.5;
        } else {
          const distPad = Math.hypot(pad.x - px, pad.z - pz);
          const speedHoriz = Math.hypot(vx, vz);

          if (phase === 'pad_approach') {
            tx = pad.x;
            tz = pad.z;
            ty = distPad > 0.35 ? 0.55 : 0.25;
            kpX = 6.5; kdX = 4.6;
            kpZ = 6.5; kdZ = 4.6;
            if (distPad < 0.09 && speedHoriz < 0.22 && py < 0.35) {
              phase = 'descend';
            }
          }

          if (phase === 'descend') {
            tx = pad.x;
            tz = pad.z;
            kpX = 7.5; kdX = 5.0;
            kpZ = 7.5; kdZ = 5.0;
            if (distPad > 0.13) {
              // Hold altitude if gust pushes us near pad edge during descent
              ty = Math.max(py, 0.16);
              vyFF = 0;
            } else {
              ty = 0.06;
              vyFF = py > 0.14 ? -0.35 : -0.15;
            }
          }
        }
      }

      // Check if we are touching down on the pad
      if (obs.gateIndex === 3) {
        const pad = obs.pad.centre;
        const distPad = Math.hypot(pad.x - px, pad.z - pz);
        const speedTotal = Math.hypot(vx, vy, vz);
        if (distPad <= 0.12 && py <= 0.088 && speedTotal < 0.42) {
          // Pin to pad with low thrust and small attitude (< 0.18 rad)
          const axPad = clamp(4.0 * (pad.x - px) - 3.0 * vx - 0.3 * wx, -1.2, 1.2);
          const azPad = clamp(4.0 * (pad.z - pz) - 3.0 * vz - 0.3 * wz, -1.2, 1.2);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchPad = clamp((cy * axPad - sy * azPad) / 9.81, -0.11, 0.11);
          const rollPad = clamp(-(sy * axPad + cy * azPad) / 9.81, -0.11, 0.11);
          prevThrustCmd = 0.06;
          return {
            thrust: 0.06,
            roll: rollPad,
            pitch: pitchPad,
            yawRate: clamp(-4.0 * att.yaw - 0.3 * rates.yaw, -2, 2),
          };
        }
      }

      // Desired accelerations
      const axDes = clamp(kpX * (tx - px) + kdX * (vxFF - vx), -5.5, 5.5);
      const azDes = clamp(kpZ * (tz - pz) + kdZ * (vzFF - vz), -5.5, 5.5);
      const ayDes = clamp(kpY * (ty - py) + kdY * (vyFF - vy), -4.0, 5.0);

      // Required specific force vector (fx, fy, fz) cancelling wind and drag
      const fx = axDes - wx + (0.42 / mEff) * vx;
      const fy = clamp(9.81 + ayDes - dyDist + (0.42 / mEff) * vy, 2.5, 18.0);
      const fz = azDes - wz + (0.42 / mEff) * vz;

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const fBx = cy * fx - sy * fz;
      const fBz = sy * fx + cy * fz;
      const fTot = Math.hypot(fBx, fy, fBz);

      let maxTilt = 0.54;
      if (obs.gateIndex === 3 && py < 0.16) maxTilt = 0.25;

      const pitchDes = clamp(Math.atan2(fBx, fy), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.asin(clamp(fBz / fTot, -0.85, 0.85)), -maxTilt, maxTilt);

      // Update reference attitude (1st order lag ~0.045s matching inner loop)
      refRoll += (rollDes - refRoll) * (dt / 0.045);
      refPitch += (pitchDes - refPitch) * (dt / 0.045);

      const rollCmd = clamp(
        rollDes + 0.50 * (rollDes - att.roll) - 0.055 * rates.roll + rollTrim,
        -0.6,
        0.6
      );
      const pitchCmd = clamp(
        pitchDes + 0.50 * (pitchDes - att.pitch) - 0.055 * rates.pitch + pitchTrim,
        -0.6,
        0.6
      );

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const tOverMReq = (9.81 + ayDes - dyDist + (0.42 / mEff) * vy) / cosTilt;
      const thrustCmd = clamp((tOverMReq * mEff) / 16.0, 0.05, 1.0);
      prevThrustCmd = thrustCmd;

      const yawRateCmd = clamp(-4.5 * att.yaw - 6.0 * yawInt - 0.35 * rates.yaw, -2, 2);

      return {
        thrust: thrustCmd,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };
    },
  };
}

