export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let wx = 0, wz = 0, dyDist = 0;
  let mEff = 0.76;
  let motorThrust = 0;
  let prevThrustCmd = 0.50;

  let rollTrim = 0, pitchTrim = 0, yawInt = 0;
  let refRoll = 0, refPitch = 0;
  let iz = 0, iy = 0;

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let prevGate = null;
  let currentGate = null;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = v.x; vy = v.y; vz = v.z;
        motorThrust = 0;
      } else {
        motorThrust += (16.0 * prevThrustCmd - motorThrust) * (1 - Math.exp(-dt / 0.038));

        const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
        const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);

        const bodyX = sp * cr, bodyZ = -sr;
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = cp * cr;
        const dirZ = -sy * bodyX + cy * bodyZ;

        const airborne = p.y > 0.082 && p.y < 2.88;
        const inRoom = Math.abs(p.x) < 2.80 && Math.abs(p.z) < 2.80;

        const ayPred = airborne ? ((motorThrust * dirY - 0.42 * vy) / mEff - 9.81 + dyDist) : 0;
        const pyPred = py + vy * dt + 0.5 * ayPred * dt * dt;
        const vyPred = vy + ayPred * dt;
        const epY = p.y - pyPred;
        const evY = v.y - vyPred;
        py = pyPred + 0.78 * epY;
        vy = vyPred + 0.68 * evY + 12.0 * epY;
        if (airborne) {
          dyDist = clamp(dyDist + 32.0 * evY + 70.0 * epY, -7.0, 7.0);
          if (Math.abs(dyDist) > 0.15) {
            const dm = clamp(-0.035 * dyDist * dt, -0.006, 0.006);
            const oldM = mEff;
            mEff = clamp(mEff + dm, 0.58, 1.08);
            dyDist += (motorThrust * dirY) * (1 / oldM - 1 / mEff);
          }
        }

        const tOverM = airborne
          ? clamp(motorThrust / mEff + dyDist / Math.max(0.5, dirY), 1.0, 28.0)
          : motorThrust / mEff;

        const ux = tOverM * dirX - (0.42 / mEff) * vx;
        const uz = tOverM * dirZ - (0.42 / mEff) * vz;
        const axPred = airborne ? (ux + wx) : 0;
        const azPred = airborne ? (uz + wz) : 0;

        const pxPred = px + vx * dt + 0.5 * axPred * dt * dt;
        const vxPred = vx + axPred * dt;
        const pzPred = pz + vz * dt + 0.5 * azPred * dt * dt;
        const vzPred = vz + azPred * dt;

        const epX = p.x - pxPred, evX = v.x - vxPred;
        const epZ = p.z - pzPred, evZ = v.z - vzPred;

        px = pxPred + 0.78 * epX;
        vx = vxPred + 0.68 * evX + 12.0 * epX;
        pz = pzPred + 0.78 * epZ;
        vz = vzPred + 0.68 * evZ + 12.0 * epZ;

        if (airborne && inRoom) {
          wx = clamp(wx + 45.0 * evX + 120.0 * epX, -12.0, 12.0);
          wz = clamp(wz + 45.0 * evZ + 120.0 * epZ, -12.0, 12.0);
        }

        if (airborne) {
          rollTrim = clamp(rollTrim + 4.2 * (refRoll - att.roll) * dt, -0.30, 0.30);
          pitchTrim = clamp(pitchTrim + 4.2 * (refPitch - att.pitch) * dt, -0.30, 0.30);
          yawInt = clamp(yawInt + att.yaw * dt, -0.6, 0.6);
        }
      }

      let tx = px, ty = 1.0, tz = pz;
      let vxFF = 0, vyFF = 0, vzFF = 0;
      let kpX = 9.0, kdX = 5.2;
      let kpZ = 12.0, kdZ = 6.0;
      let kpY = 10.0, kdY = 5.5;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          if (currentGate) prevGate = currentGate;
          currentGate = { x: gate.x, y: gate.y, z: gate.z };
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
          iz = 0;
          iy = 0;
        }

        // Brief post-gate clearance (only 12 cm past previous gate)
        if (prevGate && px < prevGate.x + 0.12) {
          tx = prevGate.x + 0.32;
          ty = prevGate.y + 0.3 * (gate.y - prevGate.y);
          tz = prevGate.z;
          vxFF = 0.85;
          kpZ = 14.0; kdZ = 6.5;
        } else {
          const dzGate = Math.abs(pz - gate.z);
          const dyGate = Math.abs(py - gate.y);

          if (dzGate < 0.08) {
            iz = clamp(iz + (gate.z - pz) * dt, -0.15, 0.15);
          } else {
            iz *= 0.9;
          }
          if (dyGate < 0.12) {
            iy = clamp(iy + (gate.y - py) * dt, -0.15, 0.15);
          } else {
            iy *= 0.9;
          }

          if (phase === 'align') {
            const xStandOff = (dzGate > 0.055 || dyGate > 0.11) ? 0.25 : 0.15;
            tx = gate.x - xStandOff;
            ty = gate.y;
            tz = gate.z;
            kpZ = dzGate < 0.12 ? 18.0 : 12.5;
            kdZ = dzGate < 0.12 ? 7.2 : 6.0;
            kpX = 9.5; kdX = 5.4;

            if (
              px > gate.x - 0.30 &&
              px < gate.x - 0.02 &&
              dzGate < 0.019 &&
              Math.abs(vz) < 0.12 &&
              dyGate < 0.075 &&
              Math.abs(vy) < 0.30
            ) {
              settle++;
            } else {
              settle = 0;
            }
            if (settle >= 2) {
              phase = 'cross';
            }
          }

          if (phase === 'cross') {
            const dxToGate = gate.x - px;
            if (dxToGate > 0.01) {
              const tCross = clamp(dxToGate / Math.max(0.35, vx), 0.01, 0.18);
              const zPred = pz + vz * tCross;
              const yPred = py + vy * tCross;
              if (
                dzGate > 0.025 ||
                Math.abs(zPred - gate.z) > 0.027 ||
                dyGate > 0.10 ||
                Math.abs(yPred - gate.y) > 0.11
              ) {
                phase = 'align';
                settle = 0;
                tx = gate.x - 0.18;
                ty = gate.y;
                tz = gate.z;
                vxFF = -0.15;
                kpX = 11.0; kdX = 5.8;
                kpZ = 18.0; kdZ = 7.2;
              } else {
                tx = gate.x + 0.35;
                ty = gate.y;
                tz = gate.z;
                vxFF = 0.95;
                kpX = 10.0; kdX = 5.2;
                kpZ = 19.0; kdZ = 7.4;
              }
            } else {
              tx = gate.x + 0.35;
              ty = gate.y;
              tz = gate.z;
              vxFF = 0.95;
              kpZ = 19.0; kdZ = 7.4;
            }
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          if (currentGate) prevGate = currentGate;
          targetIndex = 3;
          phase = 'glide';
          settle = 0;
          iz = 0;
          iy = 0;
        }

        if (prevGate && px < prevGate.x + 0.10) {
          tx = prevGate.x + 0.30;
          ty = prevGate.y - 0.15;
          tz = prevGate.z;
          vxFF = 0.85;
          kpZ = 14.0; kdZ = 6.5;
        } else {
          const distPad = Math.hypot(pad.x - px, pad.z - pz);
          const speedHoriz = Math.hypot(vx, vz);

          tx = pad.x;
          tz = pad.z;
          kpX = distPad < 0.25 ? 12.0 : 9.0;
          kdX = distPad < 0.25 ? 6.2 : 5.2;
          kpZ = distPad < 0.25 ? 12.0 : 9.0;
          kdZ = distPad < 0.25 ? 6.2 : 5.2;

          if (distPad > 0.115) {
            ty = clamp(0.14 + 0.80 * distPad, 0.15, 1.05);
            vyFF = distPad > 0.25 ? -0.35 : -0.10;
          } else {
            ty = 0.055;
            vyFF = py > 0.14 ? -0.38 : -0.18;
          }
        }
      }

      if (obs.gateIndex === 3) {
        const pad = obs.pad.centre;
        const distPad = Math.hypot(pad.x - px, pad.z - pz);
        const speedTotal = Math.hypot(vx, vy, vz);
        if (distPad <= 0.135 && py <= 0.091 && speedTotal < 0.45) {
          const axPad = clamp(5.0 * (pad.x - px) - 3.5 * vx - 0.25 * wx, -1.1, 1.1);
          const azPad = clamp(5.0 * (pad.z - pz) - 3.5 * vz - 0.25 * wz, -1.1, 1.1);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchPad = clamp((cy * axPad - sy * azPad) / 9.81, -0.11, 0.11);
          const rollPad = clamp(-(sy * axPad + cy * azPad) / 9.81, -0.11, 0.11);
          prevThrustCmd = 0.05;
          return {
            thrust: 0.05,
            roll: rollPad,
            pitch: pitchPad,
            yawRate: clamp(-4.0 * att.yaw - 0.3 * rates.yaw, -2, 2),
          };
        }
      }

      const axDes = clamp(kpX * (tx - px) + kdX * (vxFF - vx), -6.2, 6.2);
      const azDes = clamp(kpZ * (tz - pz) + kdZ * (vzFF - vz) + 8.0 * iz, -6.2, 6.2);
      const ayDes = clamp(kpY * (ty - py) + kdY * (vyFF - vy) + 6.0 * iy, -4.5, 5.5);

      const fx = axDes - wx + (0.42 / mEff) * vx;
      const fy = clamp(9.81 + ayDes - dyDist + (0.42 / mEff) * vy, 2.5, 18.0);
      const fz = azDes - wz + (0.42 / mEff) * vz;

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const fBx = cy * fx - sy * fz;
      const fBz = sy * fx + cy * fz;
      const fTot = Math.hypot(fBx, fy, fBz);

      let maxTilt = 0.56;
      if (obs.gateIndex === 3 && py < 0.15) maxTilt = 0.24;

      const pitchDes = clamp(Math.atan2(fBx, fy), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.asin(clamp(fBz / fTot, -0.85, 0.85)), -maxTilt, maxTilt);

      refRoll += (rollDes - refRoll) * (dt / 0.05);
      refPitch += (pitchDes - refPitch) * (dt / 0.05);

      const rollCmd = clamp(
        rollDes + 0.55 * (rollDes - att.roll) - 0.055 * rates.roll + rollTrim,
        -0.6,
        0.6
      );
      const pitchCmd = clamp(
        pitchDes + 0.55 * (pitchDes - att.pitch) - 0.055 * rates.pitch + pitchTrim,
        -0.6,
        0.6
      );

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const tOverMReq = (9.81 + ayDes - dyDist + (0.42 / mEff) * vy) / cosTilt;
      const thrustCmd = clamp((tOverMReq * mEff) / 16.0, 0.05, 1.0);
      prevThrustCmd = thrustCmd;

      const yawRateCmd = clamp(-4.5 * att.yaw - 6.0 * yawInt - 0.35 * rates.yaw, -2, 2);

      return {
        thrust: thrustCmd,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };
    },
  };
}
