            const xStandOff = (dzGate > 0.07 || dyGate > 0.12) ? 0.30 : 0.19;
            tx = gate.x - xStandOff;
            ty = gate.y;
            tz = gate.z;
            kpZ = 9.5; kdZ = 5.4;
            kpX = 6.8; kdX = 4.5;

