                settle = 0;
                tx = gate.x - 0.21;
                ty = gate.y;
                tz = gate.z;
                vxFF = -0.2;
                kpX = 8.5; kdX = 5.0;
                kpZ = 10.5; kdZ = 5.8;
              } else {
                tx = gate.x + 0.32;
                ty = gate.y;
                tz = gate.z;
                vxFF = 0.85;
                kpX = 7.5; kdX = 4.5;
