          const pitchPad = clamp((cy * axPad - sy * azPad) / 9.81, -0.11, 0.11);
          const rollPad = clamp(-(sy * axPad + cy * azPad) / 9.81, -0.11, 0.11);
          prevThrustCmd = 0.05;
          return {
            thrust: 0.05,
            roll: rollPad,
            pitch: pitchPad,
            yawRate: clamp(-4.0 * att.yaw - 0.3 * rates.yaw, -2, 2),
          };
        }
