      const fBx = cy * fx - sy * fz;
      const fBz = sy * fx + cy * fz;
      const fTot = Math.hypot(fBx, fy, fBz);

      let maxTilt = 0.54;
      if (obs.gateIndex === 3 && py < 0.16) maxTilt = 0.24;

      const pitchDes = clamp(Math.atan2(fBx, fy), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.asin(clamp(fBz / fTot, -0.85, 0.85)), -maxTilt, maxTilt);

      refRoll += (rollDes - refRoll) * (dt / 0.045);
      refPitch += (pitchDes - refPitch) * (dt / 0.045);

      const rollCmd = clamp(
        rollDes + 0.50 * (rollDes - att.roll) - 0.055 * rates.roll + rollTrim,
        -0.6,
        0.6
      );
      const pitchCmd = clamp(
        pitchDes + 0.50 * (pitchDes - att.pitch) - 0.055 * rates.pitch + pitchTrim,
        -0.6,
        0.6
      );

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const tOverMReq = (9.81 + ayDes - dyDist + (0.42 / mEff) * vy) / cosTilt;
      const thrustCmd = clamp((tOverMReq * mEff) / 16.0, 0.05, 1.0);
      prevThrustCmd = thrustCmd;

      const yawRateCmd = clamp(-4.5 * att.yaw - 6.0 * yawInt - 0.35 * rates.yaw, -2, 2);

      return {
        thrust: thrustCmd,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };
    },
  };
}
