        pitchDes + 0.80 * (refPitch - att.pitch) + 0.35 * (pitchDes - refPitch) - 0.06 * rates.pitch + pitchTrim,
        -0.6,
        0.6
      );

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const tOverMReq = (9.81 + ayDes - dyDist + (0.42 / mEff) * vy) / cosTilt;
      const thrustCmd = clamp((tOverMReq * mEff) / 16.0, 0.05, 1.0);
      prevThrustCmd = thrustCmd;

      const yawRateCmd = clamp(-4.5 * att.yaw - 6.0 * yawInt - 0.35 * rates.yaw, -2, 2);

      return {
        thrust: thrustCmd,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };
    },
  };
