  let px = 0, py = 0, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let wx = 0, wz = 0, dyDist = 0;
  let mEff = 0.78;
  let motorThrust = 0;
  let prevThrustCmd = 0.48;

