                ty = gate.y;
                tz = gate.z;
                vxFF = 0.75;
                kpX = 7.0; kdX = 4.5;
                kpZ = 11.0; kdZ = 6.0;
              }
            } else {
              tx = gate.x + 0.30;
              ty = gate.y;
              tz = gate.z;
              vxFF = 0.75;
