      const rollCmd = clamp(
        rollDes + 0.50 * (rollDes - att.roll) - 0.055 * rates.roll + rollFF + rollTrim,
        -0.6,
        0.6
      );
      const pitchCmd = clamp(
        pitchDes + 0.50 * (pitchDes - att.pitch) - 0.055 * rates.pitch + pitchFF + pitchTrim,
        -0.6,
        0.6
      );
      prevRollCmd = rollCmd;
      prevPitchCmd = pitchCmd;

      const yawRateCmd = clamp(-4.5 * att.yaw - 6.0 * yawInt - 0.35 * rates.yaw + yawFF, -2, 2);

      return {
        thrust: thrustCmd,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };
    },
  };
}
