      const out = {
        thrust: thrustCmd,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };
      if (actionHistory.length < 250) actionHistory.push(out);
      else actionHistory[actionHistory.length - 1] = out;
      return out;
    },
  };
