              !gustEdgeImminent &&
              px > gate.x - 0.28 &&
              px < gate.x - 0.03 &&
              dzGate < 0.017 &&
              zPredA < 0.018 &&
              Math.abs(vz) < 0.095 &&
              dyGate < 0.06 &&
              Math.abs(vy) < 0.24 &&
              Math.abs(vx) < 0.34
            ) {
