        const w1 = windAt(knownParams, obs.t + lead * 0.5);
        const w2 = windAt(knownParams, obs.t + lead);
        const wLeadX = 0.35 * w0.x + 0.40 * w1.x + 0.25 * w2.x;
        const wLeadZ = 0.35 * w0.z + 0.40 * w1.z + 0.25 * w2.z;
