        uMaxX = Math.min(0xffffffff, Math.ceil(((ox + 0.001501 + 0.045) / 0.09) * 4294967296));
        uMinZ = Math.max(0, Math.floor(((oz - 0.001501 + 0.045) / 0.09) * 4294967296));
        uMaxZ = Math.min(0xffffffff, Math.ceil(((oz + 0.001501 + 0.045) / 0.09) * 4294967296));
