            ? clamp(motorThrust / mEff + dyDist / Math.max(0.5, dirY), 1.0, 28.0)
            : motorThrust / mEff;

          const ux = tOverM * dirX - (0.42 / mEff) * vx;
          const uz = tOverM * dirZ - (0.42 / mEff) * vz;
          const axPred = airborne ? (ux + wx) : 0;
          const azPred = airborne ? (uz + wz) : 0;

