        const wLeadZ = 0.35 * w0.z + 0.40 * w1.z + 0.25 * w2.z;
        wxTotal = (0.42 / knownParams.mass) * wLeadX;
        wzTotal = (0.42 / knownParams.mass) * wLeadZ;
