      const fBx = cy * fx - sy * fz;
      const fBz = sy * fx + cy * fz;
      const fTot = Math.hypot(fBx, fy, fBz);

      let maxTilt = 0.54;
      if (obs.gateIndex === 0 && py < 0.25) maxTilt = clamp(0.18 + (py - 0.07) * 2.0, 0.18, 0.54);
      if (obs.gateIndex === 3 && py < 0.16) maxTilt = 0.24;

