          const r = mulberry((s ^ 0xa5a5a5a5) >>> 0);
          r(); r(); r();
          const py = 0.07 + (r() + r() + r() - 1.5) * 0.001;
          if (Math.abs(py - targetY) < 1e-11) {
            r(); r(); r();
            const vx = (r() + r() + r() - 1.5) * 0.018;
            if (Math.abs(vx - targetVx) < 1e-11) {
