          const axPred = airborne ? (ux + wx) : 0;
          const azPred = airborne ? (uz + wz) : 0;

          const pxPred = px + vx * dt + 0.5 * axPred * dt * dt;
          const vxPred = vx + axPred * dt;
          const pzPred = pz + vz * dt + 0.5 * azPred * dt * dt;
          const vzPred = vz + azPred * dt;

