      const fy = clamp(9.81 + ayDes - dyDist + (0.42 / massUse) * vy, 2.5, 18.0);
      const fz = azDes - wzTotal + (0.42 / massUse) * vz;

      const cy = Math.cos(curAtt.yaw), sy = Math.sin(curAtt.yaw);
